-- Studiobook initial schema for Cloudflare D1 (SQLite).
-- IDs and ISO-8601 timestamps are generated by the application.

create table studios (
  id         text primary key,
  name       text not null,
  slug       text not null,
  timezone   text not null,
  created_at text not null
);

create table studio_settings (
  studio_id                    text primary key references studios(id) on delete cascade,
  currency                     text not null,
  tax_rate_bps                 integer not null check (tax_rate_bps >= 0),
  cancellation_window_hours    integer not null check (cancellation_window_hours >= 0),
  waitlist_enabled             integer not null check (waitlist_enabled in (0, 1)),
  notify_booking_confirmations integer not null check (notify_booking_confirmations in (0, 1)),
  notify_cancellations         integer not null check (notify_cancellations in (0, 1)),
  notify_waitlist_promotions   integer not null check (notify_waitlist_promotions in (0, 1)),
  notify_invoices              integer not null check (notify_invoices in (0, 1))
);

create table members (
  id                        text primary key,
  studio_id                 text not null references studios(id) on delete cascade,
  name                      text not null,
  email                     text not null,
  phone                     text,
  status                    text not null,
  notifications_opted_out  integer not null check (notifications_opted_out in (0, 1)),
  created_at                text not null,
  unique (studio_id, email)
);

create index idx_members_studio on members (studio_id);

create table class_types (
  id                  text primary key,
  studio_id           text not null references studios(id) on delete cascade,
  name                text not null,
  description         text,
  color               text not null,
  default_capacity    integer not null check (default_capacity >= 1),
  default_price_cents integer not null check (default_price_cents >= 0),
  created_at          text not null
);

create table class_sessions (
  id            text primary key,
  studio_id     text not null references studios(id) on delete cascade,
  class_type_id text not null references class_types(id),
  instructor    text not null,
  starts_at     text not null,
  ends_at       text not null,
  capacity      integer not null check (capacity >= 1),
  price_cents   integer not null check (price_cents >= 0),
  status        text not null,
  created_at    text not null
);

create index idx_class_sessions_studio on class_sessions (studio_id);
create index idx_class_sessions_starts_at on class_sessions (starts_at);

create table bookings (
  id           text primary key,
  session_id   text not null references class_sessions(id) on delete cascade,
  member_id    text not null references members(id),
  status       text not null,
  booked_at    text not null,
  cancelled_at text
);

create index idx_bookings_session on bookings (session_id);
create index idx_bookings_member on bookings (member_id);

create table invoices (
  id             text primary key,
  studio_id      text not null references studios(id) on delete cascade,
  member_id      text not null references members(id),
  number         text not null,
  status         text not null,
  currency       text not null,
  tax_rate_bps   integer not null,
  subtotal_cents integer not null,
  tax_cents      integer not null,
  total_cents    integer not null,
  issued_at      text not null,
  due_at         text,
  paid_at        text,
  created_at     text not null,
  unique (studio_id, number)
);

create index idx_invoices_member on invoices (member_id);

create table invoice_line_items (
  id                text primary key,
  invoice_id        text not null references invoices(id) on delete cascade,
  description       text not null,
  quantity          integer not null check (quantity >= 1),
  unit_amount_cents integer not null,
  amount_cents      integer not null,
  refunded          integer not null check (refunded in (0, 1)),
  booking_id        text references bookings(id)
);

create index idx_invoice_line_items_invoice on invoice_line_items (invoice_id);

create table notification_outbox (
  id                  text primary key,
  member_id           text not null references members(id) on delete cascade,
  kind                text not null,
  payload             text not null,
  created_at          text not null,
  sent_at             text,
  provider_message_id text,
  error               text
);

create index idx_notification_outbox_sent on notification_outbox (sent_at);
